contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address[] memory tos, uint v) public {
        require(tos.length > 0);
        // address(this) is the target token: its fallback always reverts,
        // so every transferFrom call the loop makes must fail.
        bool ok = false;
        bool reverted = false;
        try c.transfer(from, address(this), tos, v) {
            ok = true;
        } catch {
            reverted = true;
        }
        assert(reverted && !ok);
    }
    fallback() external payable { revert(); }
    receive() external payable {}
}

